import{_ as t,o as a,c as s,ag as o}from"./chunks/framework.DaCm-iTo.js";const m=JSON.parse('{"title":"CoreLib Actions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/gem/corelib-actions.md","filePath":"en/modules/gem/corelib-actions.md","lastUpdated":null}'),i={name:"en/modules/gem/corelib-actions.md"};function n(d,e,r,l,h,c){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="corelib-actions" tabindex="-1">CoreLib Actions <a class="header-anchor" href="#corelib-actions" aria-label="Permalink to &quot;CoreLib Actions&quot;">​</a></h1><p>When EmakiGem is enabled, it adds main-hand gem-layer stages to the CoreLib action registry. They all operate on the target player&#39;s main-hand equipment and, when needed, read the off-hand socket opener or gem item.</p><blockquote><p>This page documents only the stages registered by EmakiGem. CoreLib built-in stages are documented in <a href="./../corelib/actions.html">CoreLib Actions</a>. Current stage IDs use only the canonical names below; historical aliases are no longer registered. The old <code>emakigem_inlay</code> is now written <code>gem_inlay</code>, and the others follow the same rule. The old <code>emakigem_upgrade_gem_item</code> has been removed and has no replacement stage.</p></blockquote><h2 id="stage-ids" tabindex="-1">Stage IDs <a class="header-anchor" href="#stage-ids" aria-label="Permalink to &quot;Stage IDs&quot;">​</a></h2><p>All four stages declare <code>REQUIRED_ENTITY</code>, and non-player targets are skipped.</p><table tabindex="0"><thead><tr><th>Stage ID</th><th>Purpose</th><th>Main input</th></tr></thead><tbody><tr><td><code>gem_open_socket</code></td><td>Opens a socket on the main-hand equipment using the off-hand opener.</td><td>Main-hand equipment, off-hand opener, <code>opener</code></td></tr><tr><td><code>gem_inlay</code></td><td>Inlays the off-hand gem into a socket on the main-hand equipment.</td><td>Main-hand equipment, off-hand gem, <code>slot</code></td></tr><tr><td><code>gem_extract</code></td><td>Extracts a gem from one socket on the main-hand equipment.</td><td>Main-hand equipment, <code>slot</code></td></tr><tr><td><code>gem_clear_layer</code></td><td>Clears the main-hand item&#39;s gem layer.</td><td>Main-hand equipment</td></tr></tbody></table><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><h3 id="gem-open-socket" tabindex="-1">gem_open_socket <a class="header-anchor" href="#gem-open-socket" aria-label="Permalink to &quot;gem_open_socket&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>opener</code></td><td>STRING</td><td>Yes</td><td>—</td><td>Socket opener ID.</td></tr><tr><td><code>slot</code></td><td>INTEGER</td><td>No</td><td><code>-1</code></td><td>Target socket slot; <code>-1</code> lets the service choose one.</td></tr><tr><td><code>bypass</code></td><td>BOOLEAN</td><td>No</td><td><code>false</code></td><td>Skips the opener item requirement.</td></tr></tbody></table><h3 id="gem-inlay-gem-extract" tabindex="-1">gem_inlay / gem_extract <a class="header-anchor" href="#gem-inlay-gem-extract" aria-label="Permalink to &quot;gem_inlay / gem_extract&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>slot</code></td><td>INTEGER</td><td>Yes</td><td>—</td><td>Target socket slot.</td></tr><tr><td><code>bypass_cost</code></td><td>BOOLEAN</td><td>No</td><td><code>false</code></td><td>Skips the configured cost.</td></tr></tbody></table><h3 id="gem-clear-layer" tabindex="-1">gem_clear_layer <a class="header-anchor" href="#gem-clear-layer" aria-label="Permalink to &quot;gem_clear_layer&quot;">​</a></h3><p>No parameters.</p><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | gem_open_socket opener=basic_socket_opener slot=-1&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | gem_open_socket opener=admin_opener slot=0 bypass=true&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | gem_inlay slot=0&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | gem_extract slot=0 bypass_cost=true&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | gem_clear_layer&#39;</span></span></code></pre></div><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Socket opening and inlay read the target player&#39;s main-hand equipment. Opening also reads the off-hand opener; inlay reads the off-hand gem.</li><li><code>gem_inlay</code> consumes one off-hand gem on success. If the service reports the input as already consumed but the operation still failed, the gem is subtracted as well, so the player does not get a free retry.</li><li>Gems returned by <code>gem_extract</code> go to the inventory, or drop at the player&#39;s feet if the inventory is full.</li><li>These stages call the existing Gem services, so configured socket opener, inlay, and extraction costs and validation still apply. <code>bypass</code> / <code>bypass_cost</code> only skips the cost checks supported by that service.</li><li>When a service declines an operation by its own rules (a missing opener, an occupied slot), the stage fails with <code>REJECTED</code> and reuses the service&#39;s existing player-facing message.</li></ul>`,17)])])}const g=t(i,[["render",n]]);export{m as __pageData,g as default};
